\label{ass:rank-law}
The function $ g:[0,\ensuremath{\left|\Omega\right|}]\longrightarrow\ensuremath{\mathbb R}\xspace$ is Lipschitz
continuous and nondecreasing. There exists a unique
$\alpha\in(0,\ensuremath{\left|\Omega\right|})$ such that $g(\alpha)=0.$ Consequently,
\begin{equation}
  g(r)<0
  \quad\text{for }r<\alpha,
  \qquad
  g(r)>0
  \quad\text{for }r>\alpha.
  \label{eq:g-sign}
\end{equation}

\label{def:weak-solution}
A function $u\in \ensuremath{\ensuremath{\operatorname H}\xspace}^{1}_0(\Omega)\cap \ensuremath{\ensuremath{\operatorname C}\xspace^{0}}(\overline\Omega)$ is a weak
solution of \eqref{eq:grad-mercier} if
\begin{equation}
  \int_\Omega
  \nabla u\cdot\nabla\phi\,\mathrm dx
  =
  \int_\Omega
  g\ensuremath{\!\left({
    \ensuremath{\left|u\geq u(x)\right|}
  }\right)}
  \phi(x)\,\mathrm dx
  \quad\:\forall\: \phi\in \ensuremath{\ensuremath{\operatorname H}\xspace}^{1}_0(\Omega).
  \label{eq:weak-problem}
\end{equation}

\label{thm:continuum-well-posedness}
Let Assumption~\ref{ass:rank-law} hold. Then \eqref{eq:grad-mercier}
admits a unique weak solution $u$. Moreover, $u\in
\ensuremath{\ensuremath{\operatorname C}\xspace^{1,1}}(\overline\Omega), \Delta u\in \ensuremath{\ensuremath{\operatorname C}\xspace^{0}}(\overline\Omega).$ The
maximum set
\begin{equation}
  D_u
  :=
  \ensuremath{\left\{{
    x\in\Omega:
    u(x)=\max_{\overline\Omega}u
  }\right\}}
  \label{eq:continuum-dead-core}
\end{equation}
has the prescribed measure
\begin{equation}
  \ensuremath{\left|D_u\right|}=\alpha.
  \label{eq:continuum-dead-core-measure}
\end{equation}
In addition,
\begin{equation}
  \ensuremath{\left|u\geq u(x)\right|}
  =
  \alpha
  \qquad
  \text{for }x\in D_u,
  \label{eq:superlevel-measure-on-dead-core}
\end{equation}
whereas
\begin{equation}
  \ensuremath{\left|u\geq u(x)\right|}
  >
  \alpha
  \qquad
  \text{for }x\in\Omega\setminus D_u.
  \label{eq:superlevel-measure-off-dead-core}
\end{equation}

\label{ass:DMP}
For every $h$, the interior stiffness matrix $A_h := \ensuremath{\!\left({
  a_h(\varphi_j,\varphi_i) }\right)}_{i,j\in\mathcal N_h^\circ} $ is an irreducible
$M$-matrix.

\label{def:discrete-problem}
The discrete problem is to find
\begin{equation}
  u_h
  :=
  \operatorname*{argmin}_{v_h\inV_h}
  \mathcal J_h(v_h).
  \label{eq:discrete-problem}
\end{equation}
Equivalently, $u_h\inV_h$ satisfies the variational inequality
\begin{equation}
  a_h(u_h,v_h-u_h)
  \geq
  \mathcal R_h(v_h)
  -
  \mathcal R_h(u_h)
  \qquad
  \text{for every }v_h\inV_h.
  \label{eq:discrete-variational-inequality}
\end{equation}

\label{thm:discrete-energy-certificate}
Let $\ensuremath{\left\{{ u_h^j,\widehat u_h^{j+1} }\right\}}_{j=0}^n$ be generated by the
rearrangement iteration
\eqref{eq:iterative-rank-source}--\eqref{eq:rearrangement-iteration}.
For $0\leq j\leq n$, define the stepwise object
\begin{equation}
  \ell_h^j
  :=
  a_h\ensuremath{\!\left({
    \widehat u_h^{j+1},u_h^j
  }\right)}
  -
  \mathcal R_h(u_h^j)
  -
  \frac12
  a_h\ensuremath{\!\left({
    \widehat u_h^{j+1},
    \widehat u_h^{j+1}
  }\right)}.
  \label{eq:iteration-lower-bound}
\end{equation}
The best floor available after $n$ iterations, the current iterate
energy, and their gap are
\begin{equation}
  L_h^n
  :=
  \max_{0\leq j\leq n}\ell_h^j,
  \qquad
  \mathcal J_h^n
  :=
  \mathcal J_h(u_h^n),
  \qquad
  \eta_h^n
  :=
  \mathcal J_h^n-L_h^n.
  \label{eq:iteration-energy-bounds}
\end{equation}
Writing $\mathcal J_h^\star := \mathcal J_h(u_h)$ for the minimum
energy, where $u_h$ is the unique discrete minimiser, we have
\begin{equation}
  L_h^n
  \leq
  \mathcal J_h^\star
  \leq
  \mathcal J_h^n.
  \label{eq:certified-energy-bracket}
\end{equation}
Consequently,
\begin{equation}
  0
  \leq
  \mathcal J_h^n-\mathcal J_h^\star
  \leq
  \eta_h^n,
  \label{eq:certified-energy-error}
\end{equation}
and
\begin{equation}
  \ensuremath{\left\|
    \nabla(u_h^n-u_h)
  \right\|}_{\ensuremath{\ensuremath{\operatorname L}\xspace^{2}}(\Omega_h)}
  \leq
  \sqrt{2\eta_h^n}.
  \label{eq:certified-energy-norm-error}
\end{equation}

\label{thm:main-nonlinear}
Let the domain and mesh hypotheses above hold, and let
Assumptions~\ref{ass:rank-law} and~\ref{ass:DMP} hold.

For every sufficiently small $h$, the discrete problem
\eqref{eq:discrete-problem} has a unique solution $u_h\in K_h.$

For every $u_h^0\in K_h$ and every step sequence satisfying
\eqref{eq:step-size-conditions}, the iteration
\eqref{eq:rearrangement-poisson-step}--\eqref{eq:rearrangement-iteration}
converges to $u_h$:
\begin{equation}
  \ensuremath{\left\|
    u_h^n-u_h
  \right\|}_{\ensuremath{\ensuremath{\operatorname H}\xspace}^{1}_0(\Omega_h)}
  \longrightarrow0
  \qquad
  \text{as }n\longrightarrow\infty.
  \label{eq:iteration-convergence}
\end{equation}
For fixed $h$, convergence also holds in $L^\infty(\Omega_h)$.

Let $u$ be the continuum solution from
Theorem~\ref{thm:continuum-well-posedness}. Then, as $h\to0$,
\begin{align}
  \mathcal E_hu_h
  &\longrightarrow u
  &&\text{strongly in }\ensuremath{\ensuremath{\operatorname H}\xspace}^{1}_0(\Omega),
  \label{eq:main-H1-convergence}
  \\
  \mathcal E_hu_h
  &\longrightarrow u
  &&\text{strongly in }\ensuremath{\ensuremath{\operatorname L}\xspace^{\infty}}(\Omega).
  \label{eq:main-Linf-convergence}
\end{align}

For each $h$, choose any admissible equilibrium source
$q_h^\ast$ satisfying \eqref{eq:discrete-source-equation}, and define
\begin{equation}
  s_h
  :=
  s_h[q_h^\ast].
  \label{eq:equilibrium-source-reconstruction}
\end{equation}
Then, independently of the choice of $q_h^\ast$, its zero extension
satisfies
\begin{equation}
  \widetilde{s_h}
  \stackrel{*}{\rightharpoonup}
  g\ensuremath{\!\left({
    \ensuremath{\left|u\geq u(\cdot)\right|}
  }\right)}
  \qquad
  \text{in }\ensuremath{\ensuremath{\operatorname L}\xspace^{\infty}}(\Omega)
  \quad\text{as }h\to0.
  \label{eq:main-source-convergence}
\end{equation}
Equivalently,
\begin{equation}
\int_\Omega
\widetilde{s_h}\varphi\,\mathrm dx
\longrightarrow
  \int_\Omega
  g\ensuremath{\!\left({
    \ensuremath{\left|u\geq u(\cdot)\right|}
    }\right)}
  \varphi\,\mathrm dx
  \qquad
  \text{for every }\varphi\in \ensuremath{\ensuremath{\operatorname L}\xspace^{1}}(\Omega).
  \label{eq:main-source-convergence-duality}
\end{equation}
In particular, the limiting solution has a maximum plateau of measure
$\alpha$ and no positive-measure level sets below its maximum.

\label{lem:nodal-measure-convergence}
For every $\psi\in \ensuremath{\ensuremath{\operatorname C}\xspace^{0}}(\overline\Omega)$,
\begin{equation}
  \int_{\overline\Omega}
  \psi
  \ensuremath{\,\mathrm{d}}\mu_h
  =
  \sum_{i\in\mathcal N_h}
  \omega_i\psi(x_i)
  =
  \int_{\Omega_h}
  I_h\psi\,\mathrm dx.
  \label{eq:nodal-quadrature}
\end{equation}
Consequently,
\begin{equation}
  \mu_h
  \rightharpoonup
  \mathcal L^2|_\Omega
  \qquad
  \text{weakly as finite measures on }\overline\Omega.
  \label{eq:mu-weak}
\end{equation}

The first identity follows from the definition of the weights and the
partition of unity:
\[
  \sum_{i\in\mathcal N_h}
  \omega_i\psi(x_i)
  =
  \int_{\Omega_h}
  \sum_{i\in\mathcal N_h}
  \psi(x_i)\varphi_i\,\mathrm dx
  =
  \int_{\Omega_h}
  I_h\psi\,\mathrm dx.
\]
Since $I_h\psi\to\psi$ uniformly on $\Omega_h$ and
$\ensuremath{\left|\Omega\setminus\Omega_h\right|}\to0$,
\[
  \ensuremath{\left|
    \int_{\overline\Omega}
    \psi\ensuremath{\,\mathrm{d}}\mu_h
    -
    \int_\Omega\psi\,\mathrm dx
  \right|}
  \leq
  \ensuremath{\left|\Omega_h\right|}
  \ensuremath{\left\|I_h\psi-\psi\right\|}_{L^\infty(\Omega_h)}
  +
  \int_{\Omega\setminus\Omega_h}
  \ensuremath{\left|\psi\right|}\,\mathrm dx
  \longrightarrow0.
\]

\label{lem:lumped-norm-equivalence}
There are constants $c,C>0$, independent of $h$, such that
\begin{equation}
  c
  \ensuremath{\left\|v_h\right\|}_{L^2(\Omega_h)}^2
  \leq
  \sum_{i\in\mathcal N_h}
  \omega_i
  \ensuremath{\left|v_h(x_i)\right|}^2
  \leq
  C
  \ensuremath{\left\|v_h\right\|}_{L^2(\Omega_h)}^2
  \label{eq:lumped-L2-equivalence}
\end{equation}
for every $v_h\in\widetilde V_h$.

\label{lem:mass-lumping-error}
For $p_h,r_h\in\widetilde V_h$,
\begin{equation}
  \ensuremath{\left|
    \sum_{i\in\mathcal N_h}
    \omega_i
    p_h(x_i)r_h(x_i)
    -
    \int_{\Omega_h}
    p_hr_h\,\mathrm dx
  \right|}
  \leq
  Ch
  \ensuremath{\left\|p_h\right\|}_{L^\infty(\Omega_h)}
  \ensuremath{\left\|\nabla r_h\right\|}_{L^2(\Omega_h)}.
  \label{eq:mass-lumping-error}
\end{equation}

\label{lem:discrete-comparison}
If $v_h,w_h\inV_h$ satisfy
\begin{equation}
  a_h(v_h,\varphi_i)
  \leq
  a_h(w_h,\varphi_i)
  \qquad
  \text{for every }i\in\mathcal N_h^\circ,
  \label{eq:comparison-assumption}
\end{equation}
then
\begin{equation}
  v_h(x_i)
  \leq
  w_h(x_i)
  \qquad
  \text{for every }i\in\mathcal N_h^\circ.
  \label{eq:comparison-conclusion}
\end{equation}

\label{lem:discrete-rearrangement-representation}
For every $v_h\inV_h$,
\begin{equation}
  \mathcal R_h(v_h)
  =
  \min_{(E_i)}
  \sum_{i\in\mathcal N_h}
  v_h(x_i)
  \int_{E_i}
  G(\rho) \ensuremath{\,\mathrm{d}}\rho.
  \label{eq:discrete-minimum-representation}
\end{equation}
The minimum assigns the lowest ranks to the largest nodal values. Thus
the nodes on a level $c\in\mathcal L_h(v_h)$ collectively receive the
rank interval
\begin{equation}
  \mathcal I_h(c;v_h).
  \label{eq:minimising-level-rank-interval}
\end{equation}

Suppose $v_h(x_i)>v_h(x_j)$, but equal-measure sets $A\subset E_i$ and
$B\subset E_j$ satisfy $\int_A G(\rho) \ensuremath{\,\mathrm{d}}\rho > \int_B G(\rho)
\ensuremath{\,\mathrm{d}}\rho.$ Exchanging $A$ and $B$ changes the pairing by
\[
  \ensuremath{\!\left({
    v_h(x_i)-v_h(x_j)
  }\right)}
  \ensuremath{\!\left({
    \int_B G(\rho) \ensuremath{\,\mathrm{d}}\rho
    -
    \int_A G(\rho) \ensuremath{\,\mathrm{d}}\rho
  }\right)}
  <
  0.
\]
Hence every minimising allocation is oppositely ordered to the nodal
values. Grouping equal values gives
\[
  \sum_{c\in\mathcal L_h(v_h)}
  c
  \int_{\mathcal I_h(c;v_h)}
  G(\rho) \ensuremath{\,\mathrm{d}}\rho
  =
  \mathcal R_h(v_h).
  \]

\label{lem:discrete-rearrangement-concavity}
The functional $\mathcal R_h:V_h\to\ensuremath{\mathbb R}\xspace$ is concave and
\begin{equation}
  \ensuremath{\left|
    \mathcal R_h(v_h)-\mathcal R_h(w_h)
  \right|}
  \leq
  M_\alpha
  \sum_{i\in\mathcal N_h}
  \omega_i
  \ensuremath{\left|
    v_h(x_i)-w_h(x_i)
  \right|}
  \label{eq:discrete-rearrangement-Lipschitz}
\end{equation}
for all $v_h,w_h\inV_h$.

\label{lem:discrete-supergradient-representation}
A functional $\ell_h\inV_h^\ast$ satisfies
\begin{equation}
  \mathcal R_h(w_h)-\mathcal R_h(v_h)
  \leq
  \ell_h(w_h-v_h)
  \qquad
  \text{for every }w_h\inV_h
  \label{eq:abstract-discrete-supergradient}
\end{equation}
if and only if there is an admissible rearrangement source
$q_h=(q_{h,i})_{i\in\mathcal N_h}$ at $v_h$ such that
\begin{equation}
  \ell_h(w_h)
  =
  \sum_{i\in\mathcal N_h}
  \omega_iq_{h,i}w_h(x_i)
  \qquad
  \text{for every }w_h\inV_h.
  \label{eq:represented-discrete-supergradient}
\end{equation}
In particular, $0\leq q_{h,i}\leq M_\alpha$.

\label{lem:discrete-energy-coercivity}
There is a constant $C>0$, independent of $h$ and $v_h$, such that
\begin{equation}
  \mathcal J_h(v_h)
  \geq
  \frac12
  \ensuremath{\left\|\nabla v_h\right\|}_{L^2(\Omega_h)}^2
  -
  C
  \ensuremath{\left\|\nabla v_h\right\|}_{L^2(\Omega_h)}.
  \label{eq:discrete-energy-coercivity}
\end{equation}

\label{lem:discrete-well-posedness}
The functional $\mathcal J_h$ has a unique minimiser $u_h\inV_h$.
Moreover, the following are equivalent:
\begin{enumerate}
  \item
  $u_h$ minimises $\mathcal J_h$;

  \item
  \begin{equation}
    a_h(u_h,v_h-u_h)
    \geq
    \mathcal R_h(v_h)-\mathcal R_h(u_h)
    \qquad
    \text{for every }v_h\inV_h;
    \label{eq:technical-discrete-VI}
  \end{equation}

  \item
  there is an admissible source
  $q_h^\ast=(q_{h,i}^\ast)_{i\in\mathcal N_h}$ at $u_h$ such that
  \begin{equation}
    a_h(u_h,v_h)
    =
    \sum_{i\in\mathcal N_h}
    \omega_iq_{h,i}^\ast v_h(x_i)
    \qquad
    \text{for every }v_h\inV_h.
    \label{eq:technical-discrete-source-equation}
  \end{equation}
\end{enumerate}

\label{lem:discrete-barrier-bound}
The discrete minimiser satisfies
\begin{equation}
  u_h\in K_h.
  \label{eq:technical-discrete-invariant-bound}
\end{equation}

\label{lem:rearrangement-iteration-convergence}
Let $u_h$ be the minimiser of $\mathcal J_h$. If
$u_h^0\in K_h$ and \eqref{eq:step-size-conditions} holds, then
\begin{equation}
  \ensuremath{\left\|
    \nabla(
      u_h^n-u_h
    )
  \right\|}_{L^2(\Omega_h)}
  \longrightarrow0.
  \label{eq:technical-iteration-H1-convergence}
\end{equation}
For fixed $h$,
\begin{equation}
  \ensuremath{\left\|
    u_h^n-u_h
  \right\|}_{L^\infty(\Omega_h)}
  \longrightarrow0.
  \label{eq:technical-iteration-Linf-convergence}
\end{equation}

\label{lem:linear-compactness-consistency}
Let $h\to0$ index a family of polygonal domains and meshes satisfying
\[
  \Omega_{-\delta_h}
  \subset
  \Omega_h
  \subset
  \Omega,
  \qquad
  \delta_h\longrightarrow0,
\]
where
\[
  \Omega_{-\delta}
  :=
  \ensuremath{\left\{{
    x\in\Omega:
    \ensuremath{\operatorname{dist}}(x,\partial\Omega)>\delta
  }\right\}}.
\]
Assume that the meshes are uniformly shape-regular and quasi-uniform.
Let $q_h=(q_{h,i})_{i\in\mathcal N_h}$ satisfy
\begin{equation}
  \sup_h
  \max_{i\in\mathcal N_h}
  \ensuremath{\left|q_{h,i}\right|}
  <\infty,
  \label{eq:uniform-nodal-source-bound}
\end{equation}
and define
\begin{equation}
  s_h
  :=
  s_h[q_h]
  =
  \sum_{i\in\mathcal N_h}
  q_{h,i}\varphi_i.
  \label{eq:linear-reconstructed-source}
\end{equation}
For any measurable function $r_h:\Omega_h\to\mathbb R$, we denote its
zero extension to $\Omega$ by
\begin{equation}
  \widetilde r_h(x)
  :=
  \begin{cases}
    r_h(x),
      &x\in\Omega_h,
    \\
    0,
      &x\in\Omega\setminus\Omega_h.
  \end{cases}
  \label{eq:source-zero-extension}
\end{equation}
This notation will be used in particular for reconstructed sources,
which need not have zero trace on $\partial\Omega_h$.

Let $U_h\inV_h$ solve
\begin{equation}
  a_h(U_h,v_h)
  =
  \sum_{i\in\mathcal N_h}
  \omega_iq_{h,i}v_h(x_i)
  \qquad
  \text{for every }v_h\inV_h.
  \label{eq:mass-lumped-linear-problem}
\end{equation}
If
\begin{equation}
  \widetilde{s_h}
  \stackrel{*}{\rightharpoonup}
  f
  \qquad
  \text{in }\ensuremath{\ensuremath{\operatorname L}\xspace^{\infty}}(\Omega)
  \quad\text{as }h\to0,
  \label{eq:reconstructed-source-weak-star}
\end{equation}
then, as $h\to0$,
\begin{align}
  \mathcal E_hU_h
  &\longrightarrow w
  &&\text{strongly in }\ensuremath{\ensuremath{\operatorname H}\xspace}^{1}_0(\Omega),
  \label{eq:linear-domain-H1-convergence}
  \\
  \mathcal E_hU_h
  &\longrightarrow w
  &&\text{strongly in }\ensuremath{\ensuremath{\operatorname L}\xspace^{\infty}}(\Omega),
  \label{eq:linear-domain-Linf-convergence}
\end{align}
where $w\in \ensuremath{\ensuremath{\operatorname H}\xspace}^{1}_0(\Omega)$ is the solution of
\begin{equation}
  \int_\Omega
  \nabla w\cdot\nabla\phi\,\mathrm dx
  =
  \int_\Omega
  f\phi\,\mathrm dx
  \qquad
  \text{for every }\phi\in \ensuremath{\ensuremath{\operatorname H}\xspace}^{1}_0(\Omega).
  \label{eq:limit-domain-poisson}
\end{equation}

The nodal bound and the partition of unity imply
\begin{equation}
  \sup_h
  \ensuremath{\left\|s_h\right\|}_{L^\infty(\Omega_h)}
  <\infty.
  \label{eq:technical-uniform-source-bound}
\end{equation}

Let $w(h)\in \ensuremath{\ensuremath{\operatorname H}\xspace}^{1}_0(\Omega_h)$ solve
\begin{equation}
  \int_{\Omega_h}
  \nabla w(h)\cdot\nabla\phi\,\mathrm dx
  =
  \int_{\Omega_h}
  s_h\phi\,\mathrm dx
  \qquad
  \text{for every }\phi\in \ensuremath{\ensuremath{\operatorname H}\xspace}^{1}_0(\Omega_h).
  \label{eq:technical-continuous-Poisson}
\end{equation}
Testing with $w(h)$ and using Poincaré's inequality gives
\begin{equation}
  \sup_h
  \ensuremath{\left\|\nabla w(h)\right\|}_{L^2(\Omega_h)}
  <\infty.
  \label{eq:technical-continuous-energy-bound}
\end{equation}

Let $z(h)\in \ensuremath{\ensuremath{\operatorname H}\xspace}^{1}_0(\Omega)$ solve the corresponding problem on the
fixed domain:
\begin{equation}
  \int_\Omega
  \nabla z(h)\cdot\nabla\phi\,\mathrm dx
  =
  \int_\Omega
  \widetilde{s_h}\phi\,\mathrm dx
  \qquad
  \text{for every }\phi\in \ensuremath{\ensuremath{\operatorname H}\xspace}^{1}_0(\Omega).
  \label{eq:technical-fixed-domain-problem}
\end{equation}
By \eqref{eq:technical-uniform-source-bound}, the zero extensions satisfy
\[
  \sup_h
  \ensuremath{\left\|
    \widetilde{s_h}
  \right\|}_{L^p(\Omega)}
  <\infty
  \qquad
  \text{for every }1\leq p<\infty.
\]
Since the fixed domain $\Omega$ has $\ensuremath{\ensuremath{\operatorname C}\xspace^{1,1}}$ boundary, elliptic
regularity therefore gives, for every fixed $p>2$,
\begin{equation}
  \ensuremath{\left\|z(h)\right\|}_{W^{2,p}(\Omega)}
  \leq
  C_p
  \ensuremath{\left\|
    \widetilde{s_h}
  \right\|}_{L^p(\Omega)}
  \leq
  C_p.
  \label{eq:technical-fixed-domain-W2p}
\end{equation}
In two dimensions,
\[
  W^{2,p}(\Omega)
  \hookrightarrow
  C^{1,\gamma}(\overline\Omega),
  \qquad
  \gamma
  =
  1-\frac{2}{p}
  >0,
\]
and the embedding
$C^{1,\gamma}(\overline\Omega)\hookrightarrow C^1(\overline\Omega)$
is compact. Hence $\{z(h)\}_h$ is precompact in
$\ensuremath{\ensuremath{\operatorname C}\xspace^{1}}(\overline\Omega)$.

If $z(h_k)\to z$ strongly in $\ensuremath{\ensuremath{\operatorname C}\xspace^{1}}(\overline\Omega)$ along a
subsequence, then passing to the limit in
\eqref{eq:technical-fixed-domain-problem} using
\eqref{eq:reconstructed-source-weak-star} shows that $z$ satisfies
\eqref{eq:limit-domain-poisson}. By uniqueness, $z=w$. Since every
convergent subsequence has the same limit, the full sequence satisfies
\begin{equation}
  z(h)
  \longrightarrow
  w
  \qquad
  \text{strongly in }\ensuremath{\ensuremath{\operatorname C}\xspace^{1}}(\overline\Omega).
  \label{eq:technical-fixed-domain-C1}
\end{equation}

We next compare the fixed-domain and varying-domain solutions. The
inclusion
\[
  \Omega_{-\delta_h}
  \subset
  \Omega_h
\]
implies
\begin{equation}
  \sup_{x\in\partial\Omega_h}
  \ensuremath{\operatorname{dist}}(x,\partial\Omega)
  \leq
  \delta_h.
  \label{eq:technical-boundary-distance}
\end{equation}
Indeed, if $x\in\partial\Omega_h$ satisfied
$\ensuremath{\operatorname{dist}}(x,\partial\Omega)>\delta_h$, then
$x\in\Omega_{-\delta_h}\subset\Omega_h$, contradicting
$x\in\partial\Omega_h$.

Since $\widetilde{s_h}=s_h$ on $\Omega_h$, the function
\[
  w(h)-z(h)|_{\Omega_h}
\]
is harmonic in $\Omega_h$ and has boundary value $-z(h)$ on
$\partial\Omega_h$. The maximum principle, the zero trace of $z(h)$ on
$\partial\Omega$, and \eqref{eq:technical-fixed-domain-W2p} give
\begin{align}
  \ensuremath{\left\|
    w(h)-z(h)
  \right\|}_{L^\infty(\Omega_h)}
  &\leq
  \ensuremath{\left\|z(h)\right\|}_{L^\infty(\partial\Omega_h)}
  \notag
  \\
  &\leq
  \ensuremath{\left\|\nabla z(h)\right\|}_{\ensuremath{\ensuremath{\operatorname L}\xspace^{\infty}}(\Omega)}
  \sup_{x\in\partial\Omega_h}
  \ensuremath{\operatorname{dist}}(x,\partial\Omega)
  \notag
  \\
  &\leq
  C\delta_h.
  \label{eq:technical-harmonic-comparison}
\end{align}
It follows from \eqref{eq:technical-fixed-domain-C1} that
\begin{equation}
  \ensuremath{\left\|
    w(h)-w
  \right\|}_{L^\infty(\Omega_h)}
  \longrightarrow0.
  \label{eq:technical-interior-Linf}
\end{equation}

It remains to control the part of $\Omega$ omitted by $\Omega_h$.
The domain inclusions give
\[
  \Omega\setminus\Omega_h
  \subset
  \ensuremath{\left\{{
    x\in\Omega:
    \ensuremath{\operatorname{dist}}(x,\partial\Omega)\leq\delta_h
  }\right\}}.
\]
Since $w\in \ensuremath{\ensuremath{\operatorname C}\xspace^{1}}(\overline\Omega)$ and $w=0$ on $\partial\Omega$,
\begin{equation}
  \ensuremath{\left\|w\right\|}_{L^\infty(\Omega\setminus\Omega_h)}
  \leq
  \delta_h
  \ensuremath{\left\|\nabla w\right\|}_{\ensuremath{\ensuremath{\operatorname L}\xspace^{\infty}}(\Omega)}
  \longrightarrow0.
  \label{eq:technical-boundary-strip}
\end{equation}
Because $\mathcal E_hw(h)=0$ on $\Omega\setminus\Omega_h$,
\eqref{eq:technical-interior-Linf} and
\eqref{eq:technical-boundary-strip} yield
\begin{equation}
  \mathcal E_hw(h)
  \longrightarrow
  w
  \qquad
  \text{strongly in }\ensuremath{\ensuremath{\operatorname L}\xspace^{\infty}}(\Omega).
  \label{eq:technical-continuous-Linf}
\end{equation}

The energy identity gives
\[
  \ensuremath{\left\|\nabla w(h)\right\|}_{L^2(\Omega_h)}^2
  =
  \int_\Omega
  \widetilde{s_h}
  \mathcal E_hw(h)
  \,\mathrm dx.
\]
By \eqref{eq:technical-continuous-Linf}, the uniform source bound and
the weak-star convergence of $\widetilde{s_h}$,
\[
  \int_\Omega
  \widetilde{s_h}
  \mathcal E_hw(h)
  \,\mathrm dx
  \longrightarrow
  \int_\Omega
  fw\,\mathrm dx
  =
  \ensuremath{\left\|\nabla w\right\|}_{L^2(\Omega)}^2.
\]
Together with weak compactness in $\ensuremath{\ensuremath{\operatorname H}\xspace}^{1}_0(\Omega)$, this proves
\begin{equation}
  \mathcal E_hw(h)
  \longrightarrow
  w
  \qquad
  \text{strongly in }\ensuremath{\ensuremath{\operatorname H}\xspace}^{1}_0(\Omega).
  \label{eq:technical-continuous-H1}
\end{equation}

Next, let $W_h\inV_h$ solve
\begin{equation}
  a_h(W_h,v_h)
  =
  \int_{\Omega_h}
  s_hv_h\,\mathrm dx
  \qquad
  \text{for every }v_h\inV_h.
  \label{eq:technical-consistent-fem-problem}
\end{equation}
Convexity of $\Omega_h$, the Miranda--Talenti estimate and Poincaré's
inequality give
\begin{equation}
  \ensuremath{\left\|w(h)\right\|}_{H^2(\Omega_h)}
  \leq
  C
  \ensuremath{\left\|s_h\right\|}_{L^2(\Omega_h)}
  \leq C.
  \label{eq:technical-uniform-H2}
\end{equation}
Céa's lemma and \eqref{eq:uniform-H1-interpolation} imply
\begin{equation}
  \ensuremath{\left\|
    \nabla(
      W_h-w(h)
    )
  \right\|}_{L^2(\Omega_h)}
  \leq
  Ch.
  \label{eq:technical-Ritz-H1}
\end{equation}
Using \eqref{eq:uniform-discrete-Sobolev} on
$W_h-I_hw(h)$, together with
\eqref{eq:uniform-Linf-interpolation}, gives
\begin{equation}
  \ensuremath{\left\|
    W_h-w(h)
  \right\|}_{L^\infty(\Omega_h)}
  \leq
  Ch
  \bigl(
    1+\ensuremath{\left|\log h\right|}
  \bigr)^{1/2}.
  \label{eq:technical-Ritz-Linf}
\end{equation}

Finally, set $e_h:=U_h-W_h$. Then
\begin{equation}
  a_h(e_h,v_h)
  =
  \sum_{i\in\mathcal N_h}
  \omega_iq_{h,i}v_h(x_i)
  -
  \int_{\Omega_h}
  s_hv_h\,\mathrm dx.
  \label{eq:technical-lumping-error-equation}
\end{equation}
Since $s_h(x_i)=q_{h,i}$, testing with $e_h$ and applying
Lemma~\ref{lem:mass-lumping-error} gives
\begin{equation}
  \ensuremath{\left\|\nabla e_h\right\|}_{L^2(\Omega_h)}
  \leq
  Ch
  \ensuremath{\left\|s_h\right\|}_{L^\infty(\Omega_h)}
  \longrightarrow0.
  \label{eq:technical-lumping-H1}
\end{equation}
The discrete Sobolev estimate gives
\begin{equation}
  \ensuremath{\left\|e_h\right\|}_{L^\infty(\Omega_h)}
  \leq
  Ch
  \bigl(
    1+\ensuremath{\left|\log h\right|}
  \bigr)^{1/2}
  \ensuremath{\left\|s_h\right\|}_{L^\infty(\Omega_h)}
  \longrightarrow0.
  \label{eq:technical-lumping-Linf}
\end{equation}
Combining the continuous-domain, Ritz and quadrature estimates proves
\eqref{eq:linear-domain-H1-convergence} and
\eqref{eq:linear-domain-Linf-convergence}.

\label{lem:continuum-rearrangement-properties}
The functional $\mathcal R:L^1(\Omega)\to\ensuremath{\mathbb R}\xspace$ is concave and
satisfies
\begin{equation}
  \ensuremath{\left|
    \mathcal R(v)-\mathcal R(w)
  \right|}
  \leq
  M_\alpha
  \ensuremath{\left\|v-w\right\|}_{L^1(\Omega)}
  \qquad
  \text{for every }v,w\in L^1(\Omega).
  \label{eq:continuum-rearrangement-Lipschitz}
\end{equation}
Consequently, $\mathcal J$ is strictly convex on $\ensuremath{\ensuremath{\operatorname H}\xspace}^{1}_0(\Omega)$.

\label{lem:continuum-no-secondary-plateaux}
Let $u$ be the continuum Grad--Mercier solution and
$M:=\max_{\overline\Omega}u$. Then
\begin{equation}
  \ensuremath{\left|
    \ensuremath{\left\{{
      x\in\Omega:
      u(x)=t
    }\right\}}
  \right|}
  =
  0
  \qquad
  \text{for every }t<M.
  \label{eq:no-lower-positive-measure-levels}
\end{equation}

\label{lem:continuum-variational-characterisation}
Let $u$ be the continuum Grad--Mercier solution and define
\begin{equation}
  q_u(x)
  :=
  G\bigl(
    \ensuremath{\left|u\geq u(x)\right|}
  \bigr).
  \label{eq:continuum-canonical-source}
\end{equation}
Then
\begin{equation}
  \mathcal R(v)-\mathcal R(u)
  \leq
  \int_\Omega
  q_u(v-u)\,\mathrm dx
  \qquad
  \text{for every }v\in L^1(\Omega),
  \label{eq:continuum-supergradient-inequality}
\end{equation}
and $u$ is the unique minimiser of $\mathcal J$.

\label{lem:discrete-rearrangement-consistency}
Let $h\to0$, and suppose that $v_h\inV_h$ satisfies
\begin{equation}
  \mathcal E_hv_h
  \longrightarrow
  v
  \qquad
  \text{uniformly on }\overline\Omega.
  \label{eq:uniform-function-convergence}
\end{equation}
Then
\begin{equation}
  \mathcal R_h(v_h)
  \longrightarrow
  \mathcal R(v)
  \qquad
  \text{as }h\to0.
  \label{eq:rearrangement-functional-convergence}
\end{equation}
